import{_ as s,o as a,c as e,a2 as i}from"./chunks/framework.CnqZ57Z3.js";const o="/flutter-tutorial-site/assets/EP.02-env-setup.Bz-W0uIq.svg",u=JSON.parse('{"title":"EP.02 doctor 全绿行动 · 开发环境搭建","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.02-env-setup.md","filePath":"comics/EP.02-env-setup.md","lastUpdated":1792665932000}'),d={name:"comics/EP.02-env-setup.md"};function l(r,t,n,c,h,p){return a(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="ep-02-doctor-全绿行动-·-开发环境搭建" tabindex="-1">EP.02 doctor 全绿行动 · 开发环境搭建 <a class="header-anchor" href="#ep-02-doctor-全绿行动-·-开发环境搭建" aria-label="Permalink to &quot;EP.02 doctor 全绿行动 · 开发环境搭建&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../guide/stage-1/02-env-setup">阶段一 · 开发环境搭建</a></p></blockquote><img src="'+o+`" alt="EP.02 doctor 全绿行动 · 开发环境搭建"><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><p>达达兴冲冲执行 <code>flutter doctor</code>，结果满屏红叉，哀嚎「装环境比写代码还难」。帧叔把环境搭建拆成「四站通关图」——SDK → doctor → IDE → 设备，并给出国内镜像配置；达达跟着「三步走」把项目跑了起来，被热重载的速度惊到。最后帧叔用一张 checklist 收束：<strong>环境一次配好，受益整个项目</strong>。</p><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="格-1-·-困境-满屏红叉" tabindex="-1">格 1 · 困境：满屏红叉 <a class="header-anchor" href="#格-1-·-困境-满屏红叉" aria-label="Permalink to &quot;格 1 · 困境：满屏红叉&quot;">​</a></h3><p><code>flutter doctor</code> 是环境体检工具，逐项检查工具链完整性。常见红叉与对策：</p><table tabindex="0"><thead><tr><th>红叉项</th><th>原因</th><th>对策</th></tr></thead><tbody><tr><td>Android toolchain</td><td>许可未接受</td><td><code>flutter doctor --android-licenses</code></td></tr><tr><td>Xcode</td><td>CocoaPods 缺失</td><td><code>brew install cocoapods</code></td></tr><tr><td>Connected device</td><td>无可用设备</td><td>启动模拟器或连真机</td></tr></tbody></table><p>红叉不可怕，它是<strong>导航而不是判决</strong>——每一条都告诉你下一步做什么。</p><h3 id="格-2-·-揭秘-四站通关图" tabindex="-1">格 2 · 揭秘：四站通关图 <a class="header-anchor" href="#格-2-·-揭秘-四站通关图" aria-label="Permalink to &quot;格 2 · 揭秘：四站通关图&quot;">​</a></h3><p>环境搭建的本质是按顺序通关四站：</p><ol><li><strong>Flutter SDK</strong>：下载 stable 渠道，把 <code>bin</code> 目录加入 <code>PATH</code></li><li><strong>doctor 体检</strong>：逐项修绿</li><li><strong>IDE 插件</strong>：VS Code 装 Flutter 扩展（自动带 Dart 扩展），或 Android Studio 装 Flutter 插件</li><li><strong>设备运行</strong>：模拟器 / 真机 / Chrome 任选其一跑通</li></ol><p>国内开发者第 0 步是先配镜像，否则 SDK 与依赖下载慢到怀疑人生：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PUB_HOSTED_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://pub.flutter-io.cn&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FLUTTER_STORAGE_BASE_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://storage.flutter-io.cn&quot;</span></span></code></pre></div><h3 id="格-3-·-实证-三步跑起来" tabindex="-1">格 3 · 实证：三步跑起来 <a class="header-anchor" href="#格-3-·-实证-三步跑起来" aria-label="Permalink to &quot;格 3 · 实证：三步跑起来&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flutter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_app</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 生成项目骨架</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my_app</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flutter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chrome</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 指定设备运行</span></span></code></pre></div><p>运行中终端的三个核心快捷键：</p><ul><li><code>r</code> <strong>热重载</strong>：保留应用状态，只刷新 UI——改界面时的日常</li><li><code>R</code> <strong>热重启</strong>：丢弃状态重新启动——改了全局状态/初始化逻辑时用</li><li><code>q</code> <strong>退出运行</strong></li></ul><h3 id="格-4-·-结案-全绿-checklist" tabindex="-1">格 4 · 结案：全绿 checklist <a class="header-anchor" href="#格-4-·-结案-全绿-checklist" aria-label="Permalink to &quot;格 4 · 结案：全绿 checklist&quot;">​</a></h3><p>交付一份可对照的验收单：SDK 入 <code>PATH</code>、镜像生效、doctor 全绿、IDE 插件就位。四项全绿，才算真正「通关」——之后所有项目共享这套环境。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">本话坑点</p><ol><li><strong>安装路径带空格或中文</strong>：Windows 上装到 <code>C:\\Program Files\\</code> 或中文目录，后续构建会报难以排查的错误，务必用纯英文无空格路径。</li><li><strong>镜像变量配了没生效</strong>：写入 <code>~/.zshrc</code> 后必须 <code>source</code> 或重开终端；在公司电脑上注意区分当前使用的 shell（zsh / bash）。</li><li><strong>首次 Android 构建卡 Gradle</strong>：国内网络拉 Gradle 依赖慢，可将 <code>android/build.gradle</code> 仓库换为阿里云镜像，耐心等待首跑。</li></ol></div><h2 id="自测-3-题" tabindex="-1">自测 3 题 <a class="header-anchor" href="#自测-3-题" aria-label="Permalink to &quot;自测 3 题&quot;">​</a></h2><p><strong>Q1</strong>：<code>flutter doctor</code> 报 <code>Android licenses status unknown</code>，应该执行什么命令？</p><details class="details custom-block"><summary>查看答案</summary><p><code>flutter doctor --android-licenses</code>，然后一路 <code>y</code> 接受全部许可。</p></details><p><strong>Q2</strong>：热重载（r）和热重启（R）的区别是什么？什么场景必须用热重启？</p><details class="details custom-block"><summary>查看答案</summary><p>热重载保留应用状态只重建 UI；热重启丢弃全部状态重新执行 <code>main()</code>。修改了全局变量初始化、<code>initState</code> 逻辑或依赖注入配置时，状态已经&quot;脏&quot;了，必须热重启才能生效。</p></details><p><strong>Q3</strong>：为什么国内建议配置 <code>PUB_HOSTED_URL</code> 和 <code>FLUTTER_STORAGE_BASE_URL</code> 两个变量？</p><details class="details custom-block"><summary>查看答案</summary><p>前者是 pub 包仓库地址（<code>flutter pub get</code> 下载第三方包用），后者是 Flutter SDK 与引擎产物的存储地址（SDK 升级、引擎下载用）。两者是独立服务，都需要镜像加速。</p></details><hr><p>上一话：<a href="./EP.01-dart-basics">EP.01 问号满天飞 · Dart 语法基础</a> ｜ 下一话：EP.03 计数器的心跳（制作中）</p>`,32)])])}const g=s(d,[["render",l]]);export{u as __pageData,g as default};
